INSERT INTO content_revision(asset_id,asset_kind,version,owner_user_id,filename,object_key,content_sha256,manifest_json,manifest_sha256,created_at,legacy_source,legacy_id) SELECT CONCAT('det-image:',LOWER(s.sha256)),'DETECTION_IMAGE',1,NULL,s.file_name,s.object_key,LOWER(s.sha256),CAST(JSON_OBJECT('id',s.`id`,'sha256',s.`sha256`,'file_name',s.`file_name`,'object_key',s.`object_key`,'status',s.`status`,'last_task_id',s.`last_task_id`,'owner_user_id',s.`owner_user_id`,'version',s.`version`,'created_at',s.`created_at`,'updated_at',s.`updated_at`) AS CHAR CHARACTER SET utf8mb4),SHA2(CAST(JSON_OBJECT('id',s.`id`,'sha256',s.`sha256`,'file_name',s.`file_name`,'object_key',s.`object_key`,'status',s.`status`,'last_task_id',s.`last_task_id`,'owner_user_id',s.`owner_user_id`,'version',s.`version`,'created_at',s.`created_at`,'updated_at',s.`updated_at`) AS CHAR CHARACTER SET utf8mb4),256),s.created_at,'detection_image_fingerprint',s.id FROM `__SOURCE_SCHEMA__`.`detection_image_fingerprint` s;
INSERT INTO runtime_state(namespace,owner_id,scope_key,revision,state_code,current_ref,payload_version,payload_json,created_at,updated_at) SELECT 'DETECTION_FINGERPRINT',0,LOWER(s.sha256),s.version,s.status,s.last_task_id,1,CAST(JSON_OBJECT('originalId',s.id,'sourceOwnerKey',s.owner_user_id) AS CHAR CHARACTER SET utf8mb4),s.created_at,s.updated_at FROM `__SOURCE_SCHEMA__`.`detection_image_fingerprint` s;
