itle`,''status'',s.`status`,''pinned'',s.`pinned`,''project_id'',NULL,''created_at'',s.`created_at`,''updated_at'',s.`updated_at`,''state_json'',s.`state_json`,''checkpoint_version'',s.`checkpoint_version`,''checkpoint_node'',s.`checkpoint_node`,''checkpoint_exit_reason'',s.`checkpoint_exit_reason`,''checkpoint_updated_at'',s.`checkpoint_updated_at`) AS CHAR CHARACTER SET utf8mb4),256) FROM `__SOURCE_SCHEMA__`.`chat_session` s;');
